sql.where:
t.del_flag = '0'

    and t.task_no like concat('%', #{bo.taskNo}, '%')


    and t.task_name like concat('%', #{bo.taskName}, '%')


    and t.task_type = #{bo.taskType}


    and t.task_status = #{bo.taskStatus}


    and t.template_id = #{bo.templateId}


    and t.route_id = #{bo.routeId}


    and t.vehicle_id = #{bo.vehicleId}


    and t.vin like concat('%', #{bo.vin}, '%')


    and t.plate_no like concat('%', #{bo.plateNo}, '%')
